Given three integer arrays a[], b[] and c[] of equal size n, find a triplet (one element from each array) that minimizes the difference between its maximum and minimum elements. If there is a tie, return the triplet with the smallest sum. The final triplet must be returned in descending order.Examples : Input : a[] = [5, 2, 8], b[] = [10, 7, 12], c[] = [9, 14, 6]Output : [7, 6, 5]Explanation: The triplet (7, 6, 5) gives the minimum possible difference between the maximum and minimum values, so it is selected.Input : a[] = [5, 12, 18, 9], b[] = [10, 17, 13, 8], c[] = [14, 16, 11, 5]Output : [11, 10, 9]Explanation: Multiple triplets have the same minimum difference, and among them (11, 10, 9) has the smallest sum, so it is chosen.Try It YourselfTable of Content[Naive Approach] Try Every Possible Triplet - O(n^3) Time and O(1) Space[Expected Approach] Sorting and Three Pointer - O(n*logn) Time and O(1) Space[Naive Approach] Try Every Possible Triplet - O(n^3) Time and O(1) SpaceWe consider each and every triplet using three nested loops and compute the difference between the maximum and minimum values in each triplet. Among all such triplets, we select the one that gives the smallest difference, updating the answer whenever a better triplet is found.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

vector<int> smallestDiff(vector<int> &a, vector<int> &b, vector<int> &c) {
    int n = a.size();
    vector<int> res(3);
    int minDiff = INT_MAX, minSum = INT_MAX;

    // Iterate over all possible triplets
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < n; k++) {
                int mx = max({a[i], b[j], c[k]});
                int mn = min({a[i], b[j], c[k]});
                int diff = mx - mn;
                int sum = a[i] + b[j] + c[k];

                // Update result if a better triplet is found
                if (diff < minDiff || (diff == minDiff && sum < minSum)) {
                    minDiff = diff;
                    minSum = sum;
                    res = {a[i], b[j], c[k]};
                }
            }
        }
    }

    // reverse sorted order
    sort(res.rbegin(), res.rend()); 
    return res;
}

int main() {
    vector<int> arr1 = {5, 2, 8};
    vector<int> arr2 = {10, 7, 12};
    vector<int> arr3 = {9, 14, 6};

    vector<int> res = smallestDiff(arr1, arr2, arr3);
    cout << res[0] << " " << res[1] << " " << res[2] << endl;


    return 0;
}


